 "content": "def transform(grid):
    """Fill gaps between same-color markers aligned in rows or columns."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda color: sum(v == color for row in grid for v in row))
    marker_colors = colors - {bg}
    if not marker_colors:
        return out
    # The demonstrations have one marker color, with 3 as the fill color.
    marker = max(marker_colors, key=lambda color: sum(v == color for row in grid for v in row))
    for r in range(h):
        points = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(points, points[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        points = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(points, points[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
